Given a string s and an integer d, the task is to left rotate the string by d positions.Examples:Input: s = "GeeksforGeeks", d = 2Output: "eksforGeeksGe"  Explanation: After the first rotation, string s becomes "eeksforGeeksG" and after the second rotation, it becomes "eksforGeeksGe".Input: s = "qwertyu", d = 2 Output: "ertyuqw" Explanation: After the first rotation, string s becomes "wertyuq" and after the second rotation, it becomes "ertyuqw".Table of Content[Naive Approach] Left Rotate one by one[Better Approach] Using Temporary Char Array [Expected Approach - 1] Using Juggling Algorithm  [Expected Approach - 2] Using Reversal Algorithm[Naive Approach] Left Rotate one by oneThe idea is to store the first character in a variable and shift all the remaining characters to the left by one position, then place the first character at the end of string. This process is repeated d times.
            C++

    // C++ Program to left rotate the string by d 
// positions by rotating one element at a time

#include <iostream>
#include <string>
using namespace std;

void rotateString(string &s, int d) {
    int n = s.size();

    // Repeat the rotation d times
    for (int i = 0; i < d; i++) {

        // Left rotate the string by one position
        int first = s[0];
        for (int j = 0; j < n - 1; j++) 
            s[j] = s[j + 1];

      	// Place the first character at the end
        s[n - 1] = first;
    }
}

int main() {
    string s = "GeeksforGeeks";
    int d = 2;
    rotateString(s, d);
    cout << s << endl;
    return 0;
}


